/// <summary>
/// MPJ_21275_BackOrders
/// Extension of SalesTable form datasource of SalesLine
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesLine))]
final class METSalesTableFormSalesLineDS_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_21275_BackOrders
    /// Based up on the SO header, Item master and Site Allow back orders check box Sales line will be activated
    /// </summary>
    /// <returns>current record</returns>
    public int active()
    {
        SalesLine           salesLine           =  this.formRun().dataSource(formDataSourceStr(SalesTable, SalesLine)).cursor(); 
        InventDim           InventDim           =  this.formRun().dataSource(formDataSourceStr(SalesTable, InventDim)).cursor();
        SalesTable          salesTable;
        METItemTypes        ItemTypes = (select firstonly ItemType from MetItemSiteSettingsSetup
                                            where MetItemSiteSettingsSetup.itemId == salesLine.ItemId
                                            && MetItemSiteSettingsSetup.inventSiteId == InventDim.InventSiteId).ItemType;
        
        select firstonly METTobaccoLicenceValidationRequired, METValidTobaccoLicence, METCustTobaccoReasonCode from salesTable 
            where salesTable.SalesId == salesLine.SalesId;
        if(salesTable.METTobaccoLicenceValidationRequired == NoYes::Yes
            && salesTable.METValidTobaccoLicence == NoYes::Yes
                && METCustParameters::Find().TobaccoFilterCodes == ItemTypes
                    && salesTable.METCustTobaccoReasonCode)
        {
            this.object(fieldNum(SalesLine, Blocked)).allowEdit(false);
        }

        /// MPJ_24819_SOParametersAndCancelLinePickList
        if(METCustParameters::find().DisableSOLineEdit)
        {
            SalesLine       metSalesLineStd;
            METSalesLine    metSalesLine;            
            boolean         setEnable;
            select firstonly OrderExtractStatus, RecId from metSalesLine
                exists join metSalesLineStd
                where metSalesLineStd.RecId == metSalesLine.SalesLine &&
                metSalesLineStd.SalesId              == salesLine.SalesId &&
                metSalesLine.OrderExtractStatus    == METOrderExtractStatus::Extracted;
            if(metSalesLine.OrderExtractStatus    == METOrderExtractStatus::Extracted)
            {
                // If already disabled by setting header controls (Complete/modify buttons) don't allow this to re-enable the salesLine
                if (!this.allowEdit())
                {                  
                    setEnable = false;                
                }
                else
                {
                    // If already enabled by setting header controls (Complete/modify buttons) but disabled by the line extracted status
                    if(salesLine.metSalesLine().RecId == metSalesLine.RecId)
                    {                   
                        setEnable = false;                       
                    }
                    else
                    {   
                        setEnable = true;                     
                    }
                }
                
            }
            else
            {            
                // If already disabled by setting header controls (Complete/modify buttons) don't allow this to re-enable the salesLine
                if (this.allowEdit())
                {
                    this.allowEdit(true);
                    setEnable = true;             
                }
            }
            this.formRun().control(this.formRun().controlId(formControlStr(SalesTable,SalesLineGrid))).allowEdit(setEnable);
            this.formRun().control(this.formRun().controlId(formControlStr(SalesTable,LineDetailsTab))).allowEdit(setEnable);
        }


        return next active();

        
    }

    /// <summary>
    ///  COC of ItemModified method
    /// </summary>
    void itemIdModified()
    {
        InventItemSalesSetup    inventItemSalesSetup;      
        FormDataSource          datasourceInventDim      = this.formRun().dataSource(formDataSourceStr(SalesTable,InventDim)) as FormDataSource ;
        SalesLine               salesLine       = this.formRun().dataSource().cursor();
        InventDim               inventDimLoc    = datasourceInventDim.cursor();
        InventDim               inventDimSales;

        next itemIdModified();

        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        select firstonly METSalesUnit from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLine.ItemId
                exists join inventDimSales
                    where inventDimSales.inventDimId == inventItemSalesSetup.InventDimId
                        &&  inventDimSales.InventSiteId == inventDimLoc.InventSiteId;

        salesLine.SalesUnit  = inventItemSalesSetup.METSalesUnit != '' ?
                               inventItemSalesSetup.METSalesUnit :
                               salesLine.SalesUnit;
        //MPJ_17845_PBMSProductMDRItemSite - End
    }

    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource metSalesLine_ds;
        METSalesLine metSalesLine;
        SalesLine metSalesLineLocal;

        next write();

        metSalesLine_ds = this.formRun().dataSource(formDataSourceStr(SalesTable, METSalesLine));
        if (metSalesLine_ds)
        {
            metSalesLineLocal = this.cursor();
            metSalesLine = metSalesLine_ds.cursor();
            metSalesLineLocal.metPackMETSalesLine(metSalesLine);
            //insert in correct order Parent, then extension
            metSalesLine.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metSalesLineLocal);
        }
    }
